local M = class("FlowerGivePopView",LikeOO.OOPopBase)
-- 花花赠送
M.m_uiName = "FlowerFestival/FlowerGivePop"  -- prefab name
M.m_size_type = 2
M.m_iphoneXAdapter = true

function M:onEnter()
    self.find_input = self:findInputField("user_input_field")
    UIUtil.addInputFieldListener(self:findGameObject("user_input_field").transform, handler(self,self.inputChanged))
    self:bindUI()
    
    self:refreshUI()
end

function M:inputChanged()
    local num = self:getSearchText()
    self.m_model:setUseNum(tonumber(num))
end

function M:getSearchText()
    return self.find_input.text
end

function M:refreshText()
    self.find_input.text = self.m_model.m_use_num
    --self:setText("use_num_text",  )
end

function M:refreshUI()
    self:refreshText()
    self:setText("text_flowerCount", self.m_model.m_existFlowerCount)
end

function M:updateUseNum()
   
end

function M:bindUI()
    self:setTextByLanKey("common_title_text", "flower_text_0005")
    self:setTextByLanKey("text_hint", "flower_text_0006")
    if self.m_model.m_tips_text_num == 1 then
        self:setTextByLanKey("text_hint", "flower_text_0024")
    end
    self:setTextByLanKey("text_max", "flower_text_0065")
    local awardItemNode = self:findGameObject("ItemNode")
    local awardUnit = RewardUtil:getProcessRewardData(self.m_model.m_itemAwardData)
    GameUtil:updateItemElementByData(awardItemNode, awardUnit, false, true)
end

function M:destroy()
    M.super.destroy(self)
end

return M
